-- wont work for bad executors
local local_player = game:GetService("Players").LocalPlayer;
local workspace = game:GetService("Workspace");

local network = require(game:GetService("ReplicatedStorage").Modules.Utility.Network);

game:GetService("RunService").RenderStepped:Connect(function()
    if (not workspace.Hooks:FindFirstChild(tostring(local_player.UserId))) then
        network.Send("RodActivated", { LuckMulti = 9e9; Mouse = { Target = workspace.World.Map.Holder.Water; Hit = CFrame.new(Vector3.zero) } });
    end
    if (local_player.Character.Head:FindFirstChild("Exclamation")) then
        network.Send("GotFish");
        network.Send("DisconnectedFishing");
    end
end);
